@Composable
fun ProductDetailScreen(
    onBackClick: () -> Unit,
    viewModel: ProductDetailViewModel = hiltViewModel()
) {
    val uiState = viewModel.uiState.collectAsState()

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF1A1A1A))
    ) {
        when {
            uiState.value.isLoading -> {
                LoadingState()
            }
            uiState.value.error != null -> {
                ErrorState(
                    error = uiState.value.error,
                    onRetry = { viewModel.retry() },
                    onBack = onBackClick
                )
            }
            uiState.value.product != null -> {
                ProductContent(
                    product = uiState.value.product!!,
                    isAddedToCart = uiState.value.isAddedToCart,
                    onAddToCart = { viewModel.addToCart() },
                    onBack = onBackClick
                )
            }
        }
    }
}

@Composable
fun ProductContent(
    product: com.example.miaumarket.core.data.remote.dto.ProductResponse,
    isAddedToCart: Boolean,
    onAddToCart: () -> Unit,
    onBack: () -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
            .padding(12.dp),
        verticalArrangement = Arrangement.SpaceBetween,
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(8.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = product.name,
                fontSize = 14.sp,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )

            if (product.price != null) {
                Text(
                    text = "€${String.format("%.2f", product.price)}",
                    fontSize = 12.sp,
                    color = Color(0xFFFF6B6B)
                )
            }

            if (!product.sourceUrl.isNullOrEmpty()) {
                Text(
                    text = "Origen: ${product.source ?: "Desconocido"}",
                    fontSize = 10.sp,
                    color = Color.Gray
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            if (product.scrapedAt != null) {
                Text(
                    text = "Actualizado: ${product.scrapedAt}",
                    fontSize = 9.sp,
                    color = Color.Gray
                )
            }
        }

        Column(
            modifier = Modifier
                .fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(8.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Button(
                onClick = onAddToCart,
                modifier = Modifier.fillMaxWidth(0.9f),
                enabled = !isAddedToCart
            ) {
                Text(if (isAddedToCart) "✓ Añadido" else "Añadir al carrito")
            }

            Button(
                onClick = onBack,
                modifier = Modifier.fillMaxWidth(0.9f)
            ) {
                Text("Atrás")
            }
        }
    }
}

@Composable
fun LoadingState() {
    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = Alignment.Center
    ) {
        Text("Cargando...", fontSize = 14.sp)
    }
}

@Composable
fun ErrorState(
    error: String,
    onRetry: () -> Unit,
    onBack: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Icon(
                imageVector = Icons.Filled.Error,
                contentDescription = null,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(40.dp),
                tint = Color(0xFFFF4444)
            )
            Text(
                text = error,
                fontSize = 11.sp,
                textAlign = TextAlign.Center
            )
            Button(onClick = onRetry) {
                Text("Reintentar")
            }
            Button(onClick = onBack) {
                Text("Atrás")
            }
        }
    }
}

package com.example.miaumarket.wear.ui.screens.product

import androidx.lifecycle.SavedStateHandle
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.miaumarket.core.data.domain.repository.ProductRepository
import com.example.miaumarket.core.data.remote.dto.ProductResponse
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

data class ProductDetailUiState(
    val product: ProductResponse? = null,
    val isLoading: Boolean = false,
    val error: String? = null,
    val isAddedToCart: Boolean = false
)

@HiltViewModel
class ProductDetailViewModel @Inject constructor(
    private val productRepository: ProductRepository,
    savedStateHandle: SavedStateHandle
) : ViewModel() {

    private val productId: Long = savedStateHandle["productId"] ?: 0L

    private val _uiState = MutableStateFlow(ProductDetailUiState())
    val uiState: StateFlow<ProductDetailUiState> = _uiState

    init {
        loadProductDetail()
    }

    private fun loadProductDetail() {
        if (productId == 0L) return

        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)

            val result = productRepository.getProductById(productId)

            result.onSuccess { product ->
                _uiState.value = _uiState.value.copy(
                    product = product,
                    isLoading = false
                )
            }

            result.onFailure { exception ->
                _uiState.value = _uiState.value.copy(
                    isLoading = false,
                    error = exception.message ?: "Error desconocido"
                )
            }
        }
    }

    fun addToCart() {
        _uiState.value = _uiState.value.copy(isAddedToCart = true)
        // Simulación de añadido al carrito
        // En una implementación real, esto interactuaría con CartRepository
    }

    fun retry() {
        loadProductDetail()
    }
}

